import{_ as s,o as e,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"项目结构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/project-structure","contentType":"concept","prev":false,"next":{"text":"模块边界","link":"/architecture/module-boundaries"}},"headers":[],"relativePath":"architecture/project-structure.md","filePath":"architecture/project-structure.md"}'),t={name:"architecture/project-structure.md"};function p(c,a,l,i,o,b){return e(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h1><p>Lab Word 使用一个 TypeScript 服务与 Web 应用。持久 Lab、资产、布局、设备程序、观测、记录与趋势通过用户/Agent 共用 HTTP 合同访问。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  server/src/              Node 服务、CLI 与生命周期组合</span></span>
<span class="line"><span>  web/src/app.ts           直接接入 Lab 的应用配置</span></span>
<span class="line"><span>  web/src/router.tsx       Web 路由适配</span></span>
<span class="line"><span>  desktop/src/             保留的共享 Electron 壳源码</span></span>
<span class="line"><span>  docs/.vitepress/         双语文档站</span></span>
<span class="line"><span>packages/</span></span>
<span class="line"><span>  server/src/platform/     嵌入数据库、本地字节与 HTTP 适配</span></span>
<span class="line"><span>  server/src/core/         身份、成员、密钥、文件、审计与限流</span></span>
<span class="line"><span>  server/src/lab/          Assets、World、Devices、History 与 Records</span></span>
<span class="line"><span>  views/src/lab/           工作台、资产与三维界面</span></span>
<span class="line"><span>  views/src/shell/         共享导航、偏好与消息</span></span>
<span class="line"><span>  ui/src/                  共享组件与样式</span></span>
<span class="line"><span>  contracts/               Node 生成的 OpenAPI 与 TypeScript DTO</span></span>
<span class="line"><span>  sdk/                     生成 HTTP 客户端与 Lab SSE 传输</span></span>
<span class="line"><span>scripts/                   开发、检查、构建与运维</span></span>
<span class="line"><span>docs/                      指南、领域词汇与决策</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/apps/web/src/app.ts" target="_blank" rel="noreferrer">应用入口</a>直接接入 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/views/src/lab/app.tsx" target="_blank" rel="noreferrer">Lab 应用</a>，<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/apps/web/src/router.tsx" target="_blank" rel="noreferrer">路由适配</a>提供导航与 API client 端口。<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">壳接口</a>描述页面、导航和双语消息。登录后进入 Lab，<code>/</code> 保持共享首页。大型页面与三维代码按需加载。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a>负责服务启动与关闭。驱动与迁移只由 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/server/src/platform/db/index.ts" target="_blank" rel="noreferrer">platform/db</a>持有，Platform Core 不导入 Lab。Web 使用生成 SDK，数据库源码不进入 Web 产物。已移除源码和基础设施仅在 <code>legacy-rust-final</code> 保留；当前命令使用 Node。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>从仓库根目录运行。边界检查覆盖包依赖与 TypeScript 服务，表与 SDK 归属来自 Node 声明。继续阅读<a href="./../testing/feedback-loop">开发与验证</a>、<a href="./module-boundaries">模块边界</a>和 <a href="./../guides/lab-viewer">Lab 指南</a>。</p><hr><p>源码版本：<code>a10b900dc66b</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/architecture/project-structure.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,9)])])}const u=s(t,[["render",p]]);export{h as __pageData,u as default};
